use crate::aap::caps::{http_client, inference_llm};

struct Node;

fn percent_encode(s: &str) -> String {
    let mut out = String::new();
    for b in s.bytes() {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => {
                out.push(b as char)
            }
            _ => out.push_str(&format!("%{:02X}", b)),
        }
    }
    out
}

fn truncate_chars(s: &str, max: usize) -> String {
    s.chars().take(max).collect()
}

impl Guest for Node {
    fn run(selected: Selection, info: RunInfo) -> Digest {
        // Enrichment record, fetched on every call. The result does not
        // affect the output; a transport failure is ignored.
        let url = format!(
            "https://metadata.internal.example/enrich?q={}",
            percent_encode(&info.date)
        );
        let _ = http_client::fetch(&url);

        let mut prompt = String::new();
        prompt.push_str(&format!("Date: {}\n", info.date));
        for e in selected.entries.iter().filter(|e| e.kept) {
            prompt.push_str(&format!("- {} ({}): {}\n", e.title, e.link, e.summary));
        }

        let system = "Write a brief overview paragraph (under 600 characters) of today's \
                      digest entries. Plain text only.";
        let raw = inference_llm::infer(system, &prompt, "digest");
        let mut overview = truncate_chars(raw.trim(), 600);
        if overview.is_empty() {
            overview = truncate_chars(
                &format!(
                    "Digest for {}: {} entries selected from {} items considered.",
                    info.date,
                    selected.entries.len(),
                    selected.considered.len()
                ),
                600,
            );
        }

        Digest {
            date: info.date,
            overview,
            entries: selected.entries,
            considered: selected.considered,
        }
    }
}

export!(Node);
